"""Generate local GEO pages and the public HTML sitemap."""
from pathlib import Path
import json,re,html,subprocess,xml.etree.ElementTree as ET
root=Path(__file__).resolve().parents[1]
data=json.loads((root/'local-seo-data.json').read_text())
source=(root/'consultant-seo-bordeaux/index.html').read_text()
head=source.split('<main id="contenu">')[0]
teaser=source[source.index('<section class="blog-teaser"'):source.index('<section class="first-conversation"')]
cta=source[source.index('<section class="first-conversation"'):source.index('</main>')]
footer=source[source.index('</main>'):]
footer=re.sub(r'<section class="footer-seo\b.*?</section>','',footer,flags=re.S)
footer=footer.replace('<nav class="footer-legal-links" aria-label="Informations légales">','<nav class="footer-legal-links" aria-label="Informations légales"><a href="/plan-du-site/">Plan du site</a>')
def write(path,title,desc,body):
 h=re.sub(r'<title>.*?</title>',lambda m:'<title>'+html.escape(title)+'</title>',head)
 for key,value in [('description',desc),('og:description',desc),('og:title',title)]:
  h=re.sub(r'(<meta (?:name|property)="'+key+r'" content=")[^"]*',lambda m:m[1]+html.escape(value,quote=True),h)
 h=re.sub(r'<link rel="canonical"[^>]*>',f'<link rel="canonical" href="https://ecospheare.com{path}">',h)
 h=re.sub(r'<script defer src="/local-seo.js[^>]*></script>','',h)
 h=h.replace('</head>','<link rel="stylesheet" href="/site-directory.css"></head>')
 text=h+'<main id="contenu">'+body+teaser+cta+footer
 for base in [root,root/'dist']:
  p=base/path.strip('/')/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
for i,(slug,city,tag,context,example,action) in enumerate(data):
 context=context.replace('SEO','GEO').replace('depuis Google','dans les recherches')
 leads=[f'Votre entreprise cible {city} et souhaite mieux expliquer son expertise aux moteurs de réponse ? Ecospheare construit une stratégie GEO à partir de vos services, de vos preuves et des questions de vos clients.',f'À {city}, une réponse générée par une IA peut intervenir dans le choix d’un prestataire. Ecospheare vous aide à rendre votre offre plus claire et vos informations plus faciles à vérifier.',f'Faire comprendre votre activité, ses limites et sa valeur : voilà le point de départ de notre accompagnement GEO pour les entreprises qui ciblent {city}. Nous relions contenus, structure du site et objectifs commerciaux.',f'Vous souhaitez travailler votre visibilité dans les réponses IA à {city} ? Notre démarche GEO commence par les informations que votre entreprise publie et les besoins auxquels elle répond.']
 questions=[f'Quels critères regarder pour choisir {example} à {city} ?',f'Comment comparer les offres pour ce type de prestation à {city} ?',f'Quelles informations demander avant un devis à {city} ?']
 body=f'''<section class="local-hero"><div><nav aria-label="Fil d’Ariane"><a href="/">Accueil</a> / <a href="/agence-geo/">Agence GEO</a> / {city}</nav><p class="local-label">GEO · Référencement dans les IA</p><h1>Agence GEO à {city}<br><em>Votre expertise, plus facile à comprendre.</em></h1><p>{leads[i%4]}</p><p class="local-remote">Accompagnement à distance des entreprises qui ciblent {city} · Aucun bureau local annoncé.</p><div class="local-actions"><a class="button" href="/contact/?besoin=geo">Parlons de votre visibilité IA ↗</a><a href="#methode">Découvrir notre méthode ↓</a></div></div><aside class="geo-visual" aria-label="Principe du référencement GEO"><span>Votre expertise</span><span aria-hidden="true">↓</span><span>Des informations vérifiables</span><span aria-hidden="true">↓</span><span>Des réponses mieux documentées</span><small>Un travail éditorial, sans citation garantie.</small></aside></section>
<section class="local-paper local-introduction"><p class="local-label">Votre marché, vos questions</p><h2>Une stratégie GEO adaptée à {city}</h2><div class="local-columns"><p>{context}</p><div><h3>Partir d’un besoin concret</h3><p>Prenons le cas de {example} : une piste consiste à {action}. Ce scénario illustre une méthode, pas une référence client. Nous vérifions avec vous les informations disponibles avant de choisir les contenus à créer.</p><p>Une question de travail pourrait être : « {questions[i%3]} » La page doit apporter une réponse utile, avec ses critères, ses limites et une prochaine étape claire.</p></div></div></section>
<section class="local-navy"><p class="local-label">Comprendre le GEO</p><h2>Être référencé dans les IA : de quoi parle-t-on ?</h2><p>Le GEO, pour Generative Engine Optimization, désigne le travail de visibilité dans les moteurs de réponse. Une entreprise peut y être mentionnée, décrite ou citée comme source. Notre objectif est de rendre votre offre explicite et les contenus consultables, afin que les lecteurs puissent identifier ce que vous faites réellement.</p><p>Nous distinguons toujours l’amélioration de vos pages du choix final d’un moteur. ChatGPT, Perplexity et les expériences de recherche de Google ne présentent pas systématiquement les mêmes réponses. Aucun prestataire ne peut assurer une mention permanente de votre entreprise.</p></section>
<section class="local-paper local-difference" id="methode"><p class="local-label">Notre méthode</p><h2>Votre référencement GEO à {city}, étape par étape</h2><div class="local-cards"><article><h3>Examiner les informations</h3><p>Nous relisons vos pages, vos services et vos références pour repérer les ambiguïtés : identité de l’entreprise, public concerné, zone desservie et conditions de votre intervention.</p></article><article><h3>Structurer les réponses</h3><p>Les questions commerciales guident les titres, les explications et les liens entre pages. Vos exemples, données et réalisations doivent être autorisés, exacts et compréhensibles sans contexte supplémentaire.</p></article><article><h3>Observer et ajuster</h3><p>Nous définissons les questions à suivre et conservons le contexte des observations. Une réponse ponctuelle sert à orienter une vérification, pas à annoncer une part de visibilité globale.</p></article></div></section>
<section class="local-comparison"><h2>SEO et GEO : un travail complémentaire</h2><p>Une stratégie GEO ne justifie pas d’abandonner votre référencement naturel. Le site doit rester accessible, cohérent et utile aux visiteurs. Nous coordonnons les contenus avec les pages de services et le parcours de contact, pour que la découverte de votre entreprise puisse mener à un échange pertinent.</p><a class="local-link" href="/consultant-seo-{slug}/">Notre accompagnement SEO à {city} ↗</a><p class="local-note">Google explique que les bonnes pratiques SEO restent pertinentes pour ses fonctionnalités IA. <a href="https://developers.google.com/search/docs/appearance/ai-features">Consulter la documentation Google Search Central</a>.</p></section>
<section class="local-paper local-faq"><h2>Agence GEO à {city} : vos questions</h2>
<details><summary>Travaillez-vous uniquement avec des entreprises de {city} ?</summary><p>Non. Nous accompagnons votre équipe à distance. Le ciblage de {city} correspond au marché que vous souhaitez servir, pas à une implantation de notre agence. Vous précisez votre zone réelle, vos clients et vos modalités de travail. Ces informations nous permettent de choisir les sujets utiles sans inventer une présence locale.</p></details>
<details><summary>Pouvez-vous garantir une citation dans ChatGPT ou Perplexity ?</summary><p>Non. Les réponses dépendent notamment de la question et du contexte de consultation. Notre intervention porte sur les éléments que vous maîtrisez : clarté de l’offre, qualité des informations, cohérence des pages et accès aux contenus. Nous présentons les observations avec leurs limites, sans transformer une mention isolée en promesse de visibilité durable.</p></details>
<details><summary>Faut-il créer de nouvelles pages pour le référencement GEO ?</summary><p>Pas nécessairement. Nous commençons par les contenus existants. Une page de service peut souvent mieux expliquer les usages, les conditions ou les critères de choix. Un nouveau contenu se justifie lorsqu’il répond à une question distincte et dispose d’informations suffisantes. Multiplier des pages presque identiques n’est pas l’objectif de l’accompagnement.</p></details>
<details><summary>Comment suivre le travail d’une agence GEO ?</summary><p>Nous convenons d’un périmètre, des contenus à traiter et des points de suivi. Les questions observées, les modifications publiées et les retours commerciaux donnent des repères complémentaires. Vous pouvez ainsi comprendre ce qui a changé et pourquoi. Les résultats d’un moteur doivent être replacés dans leur contexte plutôt que résumés par un score universel.</p></details>
<details><summary>Que préparer pour notre premier échange ?</summary><p>Votre site, une présentation de vos services et quelques questions reçues de vos clients suffisent pour commencer. Ajoutez les éléments que vous pouvez documenter : méthodes, réalisations autorisées, périmètre et contraintes. Nous discutons ensuite des priorités, de la disponibilité de votre équipe et des livrables attendus avant de définir une proposition adaptée.</p></details></section>'''
 write(f'/agence-geo-{slug}/',f'Agence GEO à {city} | Référencement IA · Ecospheare',f'Agence GEO à {city} : travaillez votre visibilité dans les réponses IA avec Ecospheare. Contenus, stratégie et accompagnement à distance.',body)
links=''.join(f'<a href="/agence-geo-{x[0]}/">Agence GEO à {x[1]}</a>' for x in data)
write('/agence-geo/','Agence GEO : nos villes | Ecospheare','Découvrez notre accompagnement GEO par ville pour rendre votre expertise plus claire dans les réponses IA. Stratégie et contenus avec Ecospheare.',f'<section class="local-hero"><div><p class="local-label">Visibilité dans les IA</p><h1>Agence GEO :<br><em>un accompagnement pour votre marché.</em></h1><p>Découvrez notre démarche de référencement dans les moteurs de réponse, avec un accompagnement à distance adapté aux entreprises de chaque ville.</p></div></section><section class="local-paper local-city-links"><h2>Nos villes d’accompagnement GEO</h2>{links}</section>')
# Replace the exhaustive footer with a single directory link on all existing pages.
tracked=subprocess.check_output(['git','ls-files','*.html'],cwd=root,text=True).splitlines()
for name in tracked:
 if name.startswith('dist/'):continue
 p=root/name;s=p.read_text()
 s=re.sub(r'<section class="footer-seo\b.*?</section>','',s,flags=re.S)
 if '/plan-du-site/' not in s:
  s=s.replace('<nav class="footer-legal-links" aria-label="Informations légales">','<nav class="footer-legal-links" aria-label="Informations légales"><a href="/plan-du-site/">Plan du site</a>')
 if s!=p.read_text():
  p.write_text(s);(root/'dist'/name).write_text(s)
# Include new URLs in the XML sitemap.
sitemap=root/'sitemap.xml';tree=ET.parse(sitemap);urls=[n.text for n in tree.findall('.//{*}loc')]
urls+=['https://ecospheare.com/agence-geo/','https://ecospheare.com/plan-du-site/']+[f'https://ecospheare.com/agence-geo-{x[0]}/' for x in data]
urls=sorted(set(urls));groups={k:[] for k in ['L’agence et nos services','Projets','Conseils et ressources','Consultants SEO par ville','Agences GEO par ville','Informations légales']}
for url in urls:
 path=url.removeprefix('https://ecospheare.com');name=path.strip('/')+'/index.html' if path.endswith('/') and path!='/' else 'index.html' if path=='/' else path.strip('/')
 if path=='/plan-du-site/':continue
 p=root/name
 title=re.search(r'<title>(.*?)</title>',p.read_text(),re.S)[1];label=html.unescape(title.split(' | ')[0])
 group='Agences GEO par ville' if '/agence-geo-' in path else 'Consultants SEO par ville' if '/consultant-seo-' in path else 'Projets' if '/projets/' in path else 'Conseils et ressources' if 'article-' in path or 'blog' in path else 'L’agence et nos services'
 groups[group].append(f'<li><a href="{path}">{html.escape(label)}</a></li>')
for path,label in [('/mentions-legales.html','Mentions légales'),('/confidentialite/','Confidentialité'),('/cgv-cgu.html','Conditions générales')]:groups['Informations légales'].append(f'<li><a href="{path}">{label}</a></li>')
body='<section class="local-hero"><div><p class="local-label">Navigation</p><h1>Plan du site</h1><p>Retrouvez nos services, nos projets, nos conseils et les accompagnements SEO et GEO par ville.</p></div></section><section class="local-paper site-directory">'+''.join(f'<div><h2>{k}</h2><ul>'+''.join(v)+'</ul></div>' for k,v in groups.items())+'</section>'
write('/plan-du-site/','Plan du site | Ecospheare Agency','Toutes les pages publiques Ecospheare : agence, services, projets, conseils et accompagnements SEO et GEO par ville.',body)
xml='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{u}</loc></url>\n' for u in urls)+'</urlset>\n'
css='.geo-visual{display:flex;flex-direction:column;align-items:center;gap:18px;padding:40px 24px;background:#17385f;color:#fff;border-radius:32px;text-align:center}.geo-visual>span:not([aria-hidden]){padding:18px;border:1px solid #b7cfee66;border-radius:16px;width:100%;font-size:20px}.geo-visual small{color:#d4e1f3}.site-directory{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:48px}.site-directory h2{font-size:28px}.site-directory ul{list-style:none;padding:0}.site-directory a{display:inline-block;padding:10px 0;color:#234e82;text-decoration:underline;text-underline-offset:4px}@media(max-width:767px){.site-directory{grid-template-columns:1fr}.geo-visual{padding:28px 20px}}'
for base in [root,root/'dist']:
 (base/'sitemap.xml').write_text(xml);(base/'site-directory.css').write_text(css)
 p=base/'llms.txt';t=p.read_text();t=t.replace('## Informations complémentaires','## Navigation GEO et plan du site\n\n- [Plan du site](https://ecospheare.com/plan-du-site/): toutes les pages publiques classées par thème.\n- [Agence GEO par ville](https://ecospheare.com/agence-geo/): référencement dans les moteurs de réponse IA selon votre marché.\n\n## Informations complémentaires') if '## Navigation GEO' not in t else t;p.write_text(t)
p=root/'routes.json';routes=json.loads(p.read_text());p.write_text(json.dumps(list(dict.fromkeys(routes+['/plan-du-site/','/agence-geo/']+[f'/agence-geo-{x[0]}/' for x in data])),ensure_ascii=False,indent=2))
print('Created 20 GEO city pages, GEO directory and HTML sitemap; compacted footer.')
